import React from 'react'
import FormProvider from '../../components/hook-form/FormProvider';
import * as Yup from 'yup';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { Alert, Button, IconButton, InputAdornment, Link, Stack } from '@mui/material';
import { RHFTextField } from '../../components/hook-form';
import { Eye, EyeSlash } from 'phosphor-react';
import { Link as RouterLink, useSearchParams } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { NewPassword } from '../../redux/slices/auth';

const NewPasswordForm = () => {

    const [showPassword, setShowPassword] = React.useState(false);
    const dispatch = useDispatch();
    const [queryParameters] = useSearchParams();

    const NewPasswordSchema = Yup.object().shape({
        newPassword: Yup.string().required("Password is required").min(8, 'Password must be atleast 8 characters'),
        confirmPassword: Yup.string().required("Password is required").oneOf([Yup.ref('newPassword'), null], 'Passwords must match'),
    });

    const defaultValues = {
        newPassword: "",
        confirmPassword: ""
    }

    const methods = useForm({
        resolver: yupResolver(NewPasswordSchema),
        defaultValues,

    });

    const { reset, setError, handleSubmit, formState: { errors, isSubmitting, isSubmitSuccessful } } = methods;

    const onSubmit = async (data) => {
        try {
            dispatch(NewPassword({ ...data, token: queryParameters.get('token') }));
        } catch (error) {
            console.log(error);
            reset();
            setError("after Submit", {
                ...error,
                message: error.message,
            })
        }
    }

    return (
        <FormProvider methods={methods} onSubmit={handleSubmit(onSubmit)}>
            <Stack spacing={3}>
                {!!errors.afterSubmit && <Alert severity='error'>{errors.afterSubmit.message}</Alert>}
                <RHFTextField name='newPassword' label="New Password" type={showPassword ? "text" : "password"} InputProps={{
                    endAdornment: (
                        <InputAdornment>
                            <IconButton onClick={() => { setShowPassword(!showPassword) }}>
                                {showPassword ? <Eye /> : <EyeSlash />}
                            </IconButton>
                        </InputAdornment>
                    )
                }} />
                <RHFTextField name='confirmPassword' label="Confirm Password" type={showPassword ? "text" : "password"} InputProps={{
                    endAdornment: (
                        <InputAdornment>
                            <IconButton onClick={() => { setShowPassword(!showPassword) }}>
                                {showPassword ? <Eye /> : <EyeSlash />}
                            </IconButton>
                        </InputAdornment>
                    )
                }} />

                <Button
                    fullWidth
                    color='inherit'
                    size='large'
                    type='submit'
                    variant='contained'
                    sx={{
                        bgcolor: 'text.primary',
                        color: (theme) => theme.palette.mode === "light" ? "common.white" : "grey.800",
                        '&:hover': {
                            bgcolor: 'text.primary',
                            color: (theme) => theme.palette.mode === 'light' ? 'common.white' : 'grey:800'
                        }
                    }}>
                    Submit
                </Button>
            </Stack>
        </FormProvider>
    )
}

export default NewPasswordForm;